fun WebhookSdk.deliveries(): Flow<Delivery> = callbackFlow {
    val subscription = subscribe(
        onDelivery = { delivery -> trySend(delivery) },   // never blocks the SDK thread
        onFailure = { error -> close(error) },           // collect throws this error
    )
    awaitClose { subscription.cancel() }                 // on take(n), cancellation, close and error
}.buffer(1_000)                                          // fused into the callbackFlow's channel

// Without awaitClose the block returns with the channel open, and collecting throws
// IllegalStateException: 'awaitClose { yourCallbackOrListener.cancel() }' should be used
// in the end of callbackFlow block.

